#include <vector>
#include <unordered_map>
#include <algorithm>
using namespace std;

class Solution {
public:
    int minimumDistance(vector<int>& nums) {
        unordered_map<int, int> last1, last2;
        int min_dist = 1e9;
        for (int i = 0; i < (int)nums.size(); ++i) {
            int x = nums[i];
            if (last2.count(x)) {
                min_dist = min(min_dist, i - last2[x]);
            }
            if (last1.count(x)) {
                last2[x] = last1[x];
            }
            last1[x] = i;
        }
        return min_dist < 1e9 ? min_dist : -1;
    }
};

import java.util.*;

class Solution {
    public int minimumDistance(int[] nums) {
        Map<Integer, Integer> last1 = new HashMap<>();
        Map<Integer, Integer> last2 = new HashMap<>();
        int minDist = Integer.MAX_VALUE;
        for (int i = 0; i < nums.length; i++) {
            int x = nums[i];
            if (last2.containsKey(x)) {
                minDist = Math.min(minDist, i - last2.get(x));
            }
            if (last1.containsKey(x)) {
                last2.put(x, last1.get(x));
            }
            last1.put(x, i);
        }
        return minDist != Integer.MAX_VALUE ? minDist : -1;
    }
}

var minimumDistance = function(nums) {
